-- Run ONCE in Supabase SQL Editor (keeps uploaded session posters)
alter table programmes add column if not exists image_url text;
alter table programmes add column if not exists speaker text;
alter table programmes add column if not exists topic text;
insert into programmes(icon,title,body,sort)
  select '', 'session', '', n from generate_series(1,4) n where not exists (select 1 from programmes where sort = n);
